function etiqueta(bulto) {
  if (bulto.pesoKg > 30) {
    return "PESADO " + bulto.pesoKg.toFixed(1) + " kg";
  }
  return "normal";
}

console.log(etiqueta({ pesoKg: 12 }));
console.log(etiqueta({ pesoKg: 8 }));
try {
  console.log(etiqueta({ pesoKg: "35" }));   // el peso llegó como texto
} catch (e) {
  console.log(e.name + ": " + e.message);
}

// Un verificador de tipos de juguete (no es TypeScript: solo ilustra la idea).
// Cada variable declara su tipo; cada línea del programa multiplica dos variables.
const declaradas = { pesoKg: "number", tarifa: "number", nota: "string" };
const valores    = { pesoKg: 12,       tarifa: 180,      nota: "frágil" };

const programa = [
  { corre: true,  izq: "pesoKg", der: "tarifa" },  // línea 1: se ejecuta siempre
  { corre: false, izq: "pesoKg", der: "nota"   },  // línea 2: una rama que casi nunca se ejecuta
];

// ESTÁTICO: mira TODAS las líneas, sin ejecutar nada y sin mirar los valores.
function verificarAntes(prog) {
  const errores = [];
  prog.forEach((l, i) => {
    const a = declaradas[l.izq], b = declaradas[l.der];
    if (a !== "number" || b !== "number") {
      errores.push(`línea ${i + 1}: ${l.izq} * ${l.der} mezcla ${a} con ${b}`);
    }
  });
  return errores;
}

// DINÁMICO: mira solo las líneas que se ejecutan, con los valores reales.
function ejecutar(prog) {
  prog.forEach((l, i) => {
    if (!l.corre) return;
    const a = valores[l.izq], b = valores[l.der];
    if (typeof a !== "number" || typeof b !== "number") {
      throw new TypeError(`línea ${i + 1}: no se puede multiplicar ${typeof a} por ${typeof b}`);
    }
    console.log(`línea ${i + 1}: ${a * b}`);
  });
}

console.log("Antes de ejecutar:", verificarAntes(programa));
ejecutar(programa);
console.log("Terminó sin errores. ¿Está bien el programa?");

